INSERT INTO `ai_assignments` (`id`, `user_id`, `resource_id`, `subject_id`, `title`, `description`, `assignment_type`, `difficulty`, `word_count`, `assignment_data`, `is_published`, `published_at`, `created_at`, `updated_at`, `due_weeks`) VALUES
(1, 2, 2, NULL, 'AI Research Assignment', NULL, 'research', 'medium', 1500, '{\"assignment\": {\"tasks\": [{\"task_title\": \"Introduction to AI Fundamentals\", \"word_count\": 250, \"description\": \"Provide a comprehensive introduction to Artificial Intelligence, defining its core principles. Differentiate clearly between supervised, unsupervised, and reinforcement learning, providing a concise example for each. Briefly explain the role of machine learning algorithms as the backbone of modern AI.\", \"task_number\": 1}, {\"task_title\": \"Deep Dive into Key AI Technologies\", \"word_count\": 450, \"description\": \"Elaborate on the specific technologies mentioned in the document: neural networks, deep learning, natural language processing (NLP), and computer vision. For each, explain its basic mechanism, key advancements, and provide a prominent example of its application. Discuss how these technologies are interconnected and contribute to advanced AI capabilities.\", \"task_number\": 2}, {\"task_title\": \"AI Applications and Industry Impact\", \"word_count\": 400, \"description\": \"Research and analyze AI applications in at least three distinct industries (e.g., healthcare, finance, automotive, education, entertainment, manufacturing). For each industry, identify specific AI tools or systems being used, describe their function, and discuss their impact (positive and negative) on efficiency, decision-making, and job roles within that sector. Provide concrete examples.\", \"task_number\": 3}, {\"task_title\": \"Ethical Considerations in AI Development\", \"word_count\": 300, \"description\": \"Investigate and discuss the ethical considerations surrounding AI development and deployment. Focus on topics such as data privacy, algorithmic bias, accountability, job displacement, and the potential for misuse. Propose strategies or frameworks that can help mitigate these ethical challenges and promote responsible AI development.\", \"task_number\": 4}, {\"task_title\": \"Conclusion and Future Outlook\", \"word_count\": 100, \"description\": \"Summarize the key findings from your research, reiterating the significance of AI in today\'s world. Conclude with a forward-looking perspective on the future trends in AI, potential breakthroughs, and the ongoing challenges that need to be addressed for its sustainable and beneficial integration into society.\", \"task_number\": 5}], \"title\": \"AI Research Assignment\", \"due_date\": \"Due in 3 weeks\", \"resources\": [\"Academic databases (e.g., IEEE Xplore, ACM Digital Library, Google Scholar, JSTOR) for peer-reviewed articles and conference papers.\", \"Reputable AI journals and conferences (e.g., AAAI, NeurIPS, ICML, CVPR, ACL).\", \"Textbooks on Machine Learning, Deep Learning, Natural Language Processing, and Computer Vision.\", \"Online courses and lectures from leading universities (e.g., Stanford\'s CS229, MIT\'s 6.034).\", \"Reports and whitepapers from leading technology companies and research institutions on AI ethics and applications.\"], \"objectives\": [\"To understand and explain fundamental AI concepts, including machine learning paradigms (supervised, unsupervised, reinforcement learning), neural networks, deep learning, natural language processing, and computer vision.\", \"To analyze and provide examples of AI applications across various industries, demonstrating an understanding of how these technologies are transforming different sectors.\", \"To critically evaluate the ethical considerations, challenges, and potential biases in AI development and deployment, proposing strategies for responsible AI.\", \"To synthesize complex information from diverse sources into a well-structured, coherent, and academically sound research report.\", \"To develop research, analytical, and critical thinking skills in the context of emerging technologies.\"], \"description\": \"This research assignment requires you to delve into the multifaceted world of Artificial Intelligence (AI), building upon the foundational concepts of machine learning algorithms, neural networks, deep learning, natural language processing, and computer vision. You will explore AI\'s diverse applications across various industries, analyze the distinctions between supervised, unsupervised, and reinforcement learning, and critically examine the ethical considerations inherent in AI development. The goal is to produce a comprehensive report that demonstrates a deep understanding of AI\'s technical underpinnings, practical implications, and societal impact. This is an intermediate-level assignment designed to foster analytical thinking and in-depth investigation.\", \"total_marks\": 100, \"evaluation_criteria\": [{\"weight\": \"40%\", \"criterion\": \"Content Quality and Accuracy\", \"description\": \"Depth of research, accuracy of information, clear definitions of concepts, relevance to the prompt, and insightful analysis of AI technologies and applications.\"}, {\"weight\": \"30%\", \"criterion\": \"Analysis and Critical Thinking\", \"description\": \"Demonstration of critical evaluation of ethical issues, thoughtful comparison of different AI approaches, and originality in insights. Ability to synthesize complex information effectively.\"}, {\"weight\": \"15%\", \"criterion\": \"Structure, Clarity, and Cohesion\", \"description\": \"Logical organization of the report, clear and concise writing style, proper use of academic language, and smooth transitions between sections. Adherence to the specified word count.\"}, {\"weight\": \"15%\", \"criterion\": \"Referencing and Academic Integrity\", \"description\": \"Correct and consistent citation of all sources using an appropriate academic style (e.g., APA, MLA, Chicago). Adherence to academic integrity policies and avoidance of plagiarism.\"}], \"submission_guidelines\": [\"The assignment must be submitted as a single PDF document through the designated online portal.\", \"The total word count should be approximately 1500 words (excluding title page, abstract, and bibliography).\", \"Use a standard academic citation style (e.g., APA 7th Edition) for all sources.\", \"Include a title page with your name, student ID, course name, assignment title, and submission date.\", \"Ensure proper grammar, spelling, and punctuation. Proofread your work carefully before submission.\", \"Plagiarism will not be tolerated and will result in a failing grade for the assignment.\"]}}', 0, NULL, '2026-01-04 18:59:05', '2026-01-04 18:59:05', 3),
(2, 2, 10, 4, 'time series assignment', NULL, 'research', 'medium', 1000, '{\"assignment\": {\"tasks\": [{\"task_title\": \"Foundational Concepts and Data Pre-processing\", \"word_count\": 350, \"description\": \"Provide a detailed explanation of the following foundational time series concepts. For each concept, describe its definition, importance in time series analysis, and practical implications. Illustrate how these concepts contribute to preparing data for effective modeling.\\n\\n1.  **Stationarity and Differencing**: Explain what stationarity means in the context of time series, why it is crucial for many forecasting models (e.g., ARIMA), and describe the primary methods, particularly differencing (first-order and second-order), used to achieve it. Provide a hypothetical example of a non-stationary series and how differencing would transform it.\\n2.  **White Noise**: Define white noise and explain its characteristics (mean, variance, autocorrelation). Discuss its significance as a benchmark for model residuals and what it indicates about a fitted model.\\n3.  **Moving Average (MA) for Smoothing**: Describe the concept of a Moving Average as a smoothing technique. Explain how it works to reduce noise and highlight trends, differentiating between Simple Moving Average (SMA) and Weighted Moving Average (WMA) in terms of their application and impact on data. Provide a real-world scenario where a moving average would be beneficial (e.g., stock prices, sales data).\", \"task_number\": 1}, {\"task_title\": \"Model Identification, Selection, and Comparison\", \"word_count\": 450, \"description\": \"This task focuses on understanding and applying advanced time series models and diagnostic tools.\\n\\n1.  **ARIMA and SARIMA Models**: Explain the components of an ARIMA(p, d, q) model (AR, I, MA) and how each addresses specific characteristics of a time series. Subsequently, detail how SARIMA(p, d, q)(P, D, Q)m extends ARIMA to handle seasonality, explaining the role of the seasonal terms (P, D, Q) and the length of seasonality (m).\\n2.  **ACF and PACF for Model Identification**: Describe the Autocorrelation Function (ACF) and Partial Autocorrelation Function (PACF). Explain how these plots are used in conjunction to identify the appropriate orders (p, d, q, P, D, Q) for ARIMA and SARIMA models. Provide a detailed example of how you would interpret hypothetical ACF and PACF plots to suggest initial AR and MA orders for a non-seasonal time series.\\n3.  **Comparison of Forecasting Techniques**: Compare and contrast ARIMA/SARIMA models with Exponential Smoothing techniques (Simple, Double, Triple). Discuss their underlying assumptions, strengths, weaknesses, and the types of time series data (e.g., with/without trend, seasonality) for which each approach is most suitable. Provide a scenario where Exponential Smoothing might be preferred over ARIMA, and vice-versa.\", \"task_number\": 2}, {\"task_title\": \"Time Series Decomposition and Holistic Modeling Process\", \"word_count\": 200, \"description\": \"This task requires you to synthesize your understanding of time series analysis into a coherent modeling strategy.\\n\\n1.  **Time Series Decomposition**: Explain the concept of time series decomposition, detailing its components: Trend (T), Seasonality (S), and Residual (R). Describe how decomposing a time series (e.g., using an additive model: Time Series = T + S + R) aids in understanding the underlying patterns and informs subsequent modeling decisions.\\n2.  **The Iterative Modeling Process**: Outline a general iterative process for building and validating a time series forecasting model, integrating the concepts discussed in Tasks 1 and 2. This should include steps such as initial data analysis, achieving stationarity, model identification (using ACF/PACF), parameter estimation, model fitting, residual analysis (checking for white noise), and forecasting. Discuss the importance of each step in ensuring a robust and accurate forecast.\\n3.  **Challenges in Real-World Forecasting**: Briefly discuss at least two common challenges encountered when applying time series forecasting techniques in real-world scenarios (e.g., data quality issues, structural breaks, choice of evaluation metrics, model interpretability vs. accuracy).\", \"task_number\": 3}], \"title\": \"time series assignment\", \"due_date\": \"Due in 2 weeks\", \"resources\": [\"Provided Document: TimeSeries PDF Content (Primary resource for core concepts)\", \"Introductory Textbooks on Time Series Analysis (e.g., \'Forecasting: Principles and Practice\' by Hyndman and Athanasopoulos, \'Time Series Analysis and Its Applications\' by Shumway and Stoffer)\", \"Online Courses and Tutorials on Time Series Forecasting (e.g., Coursera, edX, DataCamp modules on time series)\", \"Documentation for Time Series Libraries in statistical programming languages (e.g., Python\'s `statsmodels` or `pmdarima` packages; R\'s `forecast` package)\"], \"objectives\": [\"Define and explain core time series concepts such as stationarity, white noise, and differencing, and articulate their significance.\", \"Understand the structure, components, and application of AutoRegressive Integrated Moving Average (ARIMA) and Seasonal ARIMA (SARIMA) models.\", \"Utilize Autocorrelation Function (ACF) and Partial Autocorrelation Function (PACF) for effective time series model identification.\", \"Explain the process of time series decomposition and the principles of Exponential Smoothing.\", \"Critically compare and contrast different time series forecasting techniques, discussing their strengths, weaknesses, and appropriate use cases.\", \"Synthesize theoretical knowledge to propose suitable modeling approaches for various time series characteristics.\"], \"description\": \"This research assignment is designed to deepen your understanding of fundamental concepts, models, and diagnostic tools in time series analysis. Time series data, which is sequential data indexed by time, is ubiquitous in various fields such as finance, economics, meteorology, and engineering. Accurate forecasting and pattern recognition in time series are crucial for informed decision-making. This assignment requires you to analyze, explain, and critically compare key time series methodologies based on the provided document content and supplementary research. You will demonstrate your ability to articulate complex concepts, apply them to hypothetical scenarios, and understand their practical implications in real-world forecasting challenges. The assignment aims to foster a comprehensive grasp of time series modeling, from data preparation to model selection and interpretation.\", \"total_marks\": 100, \"evaluation_criteria\": [{\"weight\": \"40%\", \"criterion\": \"Content Accuracy and Depth\", \"description\": \"Correctness of definitions, explanations, and examples. Thoroughness and accuracy in describing concepts, models, and their applications. Evidence of deep understanding beyond surface-level definitions.\"}, {\"weight\": \"25%\", \"criterion\": \"Clarity, Cohesion, and Structure\", \"description\": \"The assignment is well-organized with a logical flow of ideas. Explanations are clear, concise, and easy to understand. Proper use of academic language and terminology.\"}, {\"weight\": \"20%\", \"criterion\": \"Critical Analysis and Comparison\", \"description\": \"Ability to critically analyze concepts, compare different models and techniques, discuss their strengths, weaknesses, and appropriate use cases. Insightful interpretation of diagnostic tools like ACF/PACF.\"}, {\"weight\": \"10%\", \"criterion\": \"Adherence to Word Count and Formatting\", \"description\": \"Meeting the specified word counts for each task and overall. Adherence to any specified formatting guidelines (if applicable, beyond JSON structure).\"}, {\"weight\": \"5%\", \"criterion\": \"Referencing and Research (Implicit)\", \"description\": \"While the primary resource is provided, demonstrating an understanding that extends to broader implications or acknowledging where further research would be beneficial. (No formal referencing required unless external sources are explicitly used).\"}], \"submission_guidelines\": [\"Submit your assignment as a single PDF document.\", \"Ensure each task is clearly labeled with its task number and title.\", \"Maintain a professional and academic tone throughout your writing.\", \"Adhere strictly to the specified word counts for each task.\", \"Plagiarism will not be tolerated. All work must be original. If external sources are consulted beyond the provided document, they must be properly cited.\"]}}', 0, NULL, '2026-01-06 11:46:19', '2026-01-06 11:46:19', 2),
(3, 2, 10, 4, 'time series assignment', NULL, 'research', 'medium', 500, '{\"assignment\": {\"tasks\": [{\"task_title\": \"Foundations of Time Series Analysis: Conceptual Research and Synthesis\", \"word_count\": 200, \"description\": \"Research and explain the foundational concepts of time series analysis. Specifically, address the following:\\n\\na) Define \'stationarity\' in time series modeling and explain its critical importance for forecasting models like ARIMA. Describe at least two methods to achieve stationarity, referencing the \'differencing\' concept.\\n\\nb) Detail the components of an ARIMA(p, d, q) model (AR, I, MA), explaining how each contributes to capturing patterns in time series data.\\n\\nc) Explain the roles of the Autocorrelation Function (ACF) and Partial Autocorrelation Function (PACF) in identifying the orders (p and q) of AR and MA components, respectively. Provide a conceptual example of how their plots would guide parameter selection.\", \"task_number\": 1}, {\"task_title\": \"Advanced Models and Decomposition: Comparative Analysis\", \"word_count\": 180, \"description\": \"Investigate and compare advanced time series techniques and models. Address the following:\\n\\na) Explain the concept of \'Time Series Decomposition\' (Trend, Seasonality, Residual). Discuss how decomposing a series aids in understanding its underlying structure and informs model selection.\\n\\nb) Compare SARIMA and Exponential Smoothing (specifically mentioning Holt-Winters Triple Exponential Smoothing). For what types of time series data (e.g., presence of trend, seasonality, or emphasis on recent observations) would each model be most appropriate? Provide a brief justification for each.\", \"task_number\": 2}, {\"task_title\": \"Application and Critical Thinking: Scenario-Based Investigation\", \"word_count\": 120, \"description\": \"Consider a hypothetical scenario: You are tasked with forecasting monthly electricity consumption for a large city. You observe that the data shows a clear upward trend over the years and distinct seasonal peaks during summer and winter months. Additionally, there are occasional unpredictable spikes due to extreme weather events.\\n\\nBased on the concepts from the provided document and your research, propose the most suitable time series modeling approach for this scenario. Justify your choice by explaining why the selected method is appropriate for the observed data characteristics. Outline the key steps you would take to implement and evaluate this model, including any necessary data transformations.\", \"task_number\": 3}], \"title\": \"Time Series Analysis and Forecasting: A Research Assignment\", \"due_date\": \"Due in 2 weeks\", \"resources\": [\"The provided \'TimeSeries PDF\' document content.\", \"Academic textbooks or reputable online resources on Time Series Analysis and Forecasting (e.g., \'Forecasting: Principles and Practice\' by Hyndman and Athanasopoulos).\", \"Documentation for statistical software libraries (e.g., Python\'s `statsmodels`, R\'s `forecast` package) for practical context.\"], \"objectives\": [\"To define and explain core time series concepts such as stationarity, differencing, ARIMA components, ACF, and PACF.\", \"To compare and contrast advanced time series models like SARIMA and Exponential Smoothing, and understand the utility of time series decomposition.\", \"To critically analyze hypothetical time series scenarios and propose appropriate modeling strategies based on data characteristics.\", \"To synthesize information from the provided document and external resources to formulate well-reasoned explanations and justifications.\"], \"description\": \"This assignment requires you to delve into the fundamental and advanced concepts of time series analysis, drawing upon the provided document content and supplementary research. You will analyze key methodologies, understand their underlying principles, and apply critical thinking to propose solutions for real-world time series challenges. The goal is to develop a comprehensive understanding of how time series data is characterized, modeled, and forecasted.\", \"total_marks\": 100, \"evaluation_criteria\": [{\"weight\": \"40%\", \"criterion\": \"Content Accuracy and Depth\", \"description\": \"Accuracy of definitions, explanations, and understanding of time series concepts. Depth of analysis and insight provided in comparing models and justifying choices.\"}, {\"weight\": \"30%\", \"criterion\": \"Analytical Rigor and Justification\", \"description\": \"Clarity and logical coherence of arguments, especially in Task 3\'s scenario analysis. Effectiveness of justifications for model selection and proposed steps.\"}, {\"weight\": \"20%\", \"criterion\": \"Clarity, Organization, and Synthesis\", \"description\": \"Overall clarity of writing, logical flow between sections, and effective synthesis of information from various sources. Adherence to assignment structure.\"}, {\"weight\": \"10%\", \"criterion\": \"Adherence to Word Count and Instructions\", \"description\": \"Meeting the specified word counts for each task and following all formatting and submission guidelines.\"}], \"submission_guidelines\": [\"Submit your assignment as a single document (e.g., PDF or Word document).\", \"Ensure all tasks are clearly labeled with their respective task numbers and titles.\", \"Cite any external sources used beyond the provided document content.\", \"Adhere strictly to the specified word counts for each task. Deviations of more than 10% may result in penalties.\"]}}', 1, '2026-01-06 06:17:59', '2026-01-06 11:47:34', '2026-01-06 11:47:59', 2);

